// 模拟TCP拥塞窗口变化
class CongestionControl {
    double cwnd = 1.0;       // 拥塞窗口(单位: MSS)
    double ssthresh = 64.0;  // 慢启动阈值
    String state = "slow_start";

    // 每收到一个ACK调用
    void onAckReceived() {
        switch (state) {
            case "slow_start":
                cwnd += 1.0;  // 每个ACK使cwnd增加1 MSS
                if (cwnd >= ssthresh) {
                    state = "congestion_avoidance";
                }
                break;
            case "congestion_avoidance":
                cwnd += 1.0 / cwnd;  // 每个RTT增加1 MSS
                break;
            case "fast_recovery":
                cwnd += 1.0;  // 收到新ACK，保持拥塞避免
                state = "congestion_avoidance";
                break;
        }
        System.out.printf("ACK: cwnd=%.2f, ssthresh=%.0f, state=%s%n",
                          cwnd, ssthresh, state);
    }

    // 检测到丢包
    void onPacketLoss(boolean isTimeout) {
        ssthresh = cwnd / 2;
        if (isTimeout) {
            // 超时: 严重拥塞，重新慢启动
            cwnd = 1.0;
            state = "slow_start";
        } else {
            // 3个重复ACK: 轻度拥塞，快恢复
            cwnd = ssthresh + 3;
            state = "fast_recovery";
        }
    }
}

// 模拟运行
CongestionControl cc = new CongestionControl();
for (int rtt = 0; rtt < 10; rtt++) {
    for (int ack = 0; ack < (int)cc.cwnd; ack++) {
        cc.onAckReceived();
    }
}
